-- 007: Japanese (ja) translations for places & dishes
INSERT INTO translations (entity_type, entity_id, language_id, name, short_description, description, history, cultural_significance, tourist_tips)
SELECT 'place', p.id, l.id, v.name, v.short_desc, v.descr, v.history, v.culture, v.tips
FROM (VALUES
  ('oc-oanh', 'オー・オアン（貝料理）',
   '4区で有名な屋台スタイルの貝料理店。夕方から営業し、炭火で貝を焼く南房独自の香ばしい味わい。',
   'オー・オアンは第四郡の住民に親しまれてきた海鮮屋台で、炭火焼きや炒めの貝料理、レモングラス蒸しのハマグリなどが名物だ。歩道に並ぶ小さなプラスチックテーブルで、夜に仲間と楽しむのにぴったりである。店は午後から深夜まで営業し、いつ訪れても笑い声と炭火の音が絶えない。ほとんどのメニューは注文を受けてから調理され、貝の新鮮さと手間ひまかけた本格的な味が同時に味わえる。貝の弾力感と、バター・ニンニク・唐辛子・ベトナム南部のスパイスが絡み合う特別な風味が特徴だ。アイスティーで喉を潤し、甘酸っぱいディップソース、焼きライスペーパーが全部のバランスを整えてくれる。地元民に限らず、最近ではわざわざ遠くから来る旅行者も増え、道端の小さな店に込みあがる煙と街場の雰囲気を満喫し、写真を撮り、都市のエッセンスを体験している。来店者はよく貝料理と一緒に焼きライスペーパーやクリスピーフライドライス、冷たいビールを頼み、夜をにぎやかに彩る。焼き卵やバターポップコーンのようなサイドメニューもあるため、食事体験がさらに味わい深くなる。週末になると若い仲間同士が会う人気スポットに変わり、道端の小さなプラスチックテーブルで過ごした時間が忘れがたい思い出になっていく。',
   '店はドアン・ヴァン・クー通りにあり、夕方から深夜まで営業している。メニューは毎朝届く新鮮な貝類を中心に、サイゴン流の炭火焼き・ニンニク炒め・レモングラス蒸しの様式で提供される。 海鮮は毎日朝に港や川から運び込まれ、常に生き生きとしている。炭火の竈が一日中燃え続け、独特の香ばしい煙の香りを街中に漂わせる。大きな看板はなくとも、料理の味と長年のお客とのご縁だけで細く長く続けてきた店だ。昨今はSNSに上がった炭火の映像が若い客を引き寄せており、フードツーリストの聖地としてさらに注目されている。時代が変わっても代々伝わる家庭の味、手の奥深さがこの店の最も輝く部分だ。',
   '貝料理は、仕事帰りに友人と集まるサイゴンの屋台食文化を象徴する。4区は市内でも貝料理店が最も密集するエリアの一つで、数十年変わらず活気を保っている。炭火の色と熱、濃い味わいが合わさり、街のハイライトをつくるこの情景は沿岸貿易の長い歴史ともつながっている。地元の人にとって貝料理店は仕事後の仲間との再会、雑談、分け共有の非公式空間であり、華やかではないが本当に温かみのある場所だ。',
   '夕方18時以降に訪れてナイトマーケットの雰囲気を楽しんでください • 焼きライスペーパーやせんべいと一緒にどうぞ • 多くの店が現金のみですので、現金をご用意ください • 塩こしょう焼きカブトムシをライムの葉と一緒に試してみてください • スタッフにおすすめの組み合わせを尋ね、思い切り楽しんでください'),
  ('com-tam-vinh-khanh', 'ヴィン・カイン コータム',
   'ヴィン・カイン通りのサイゴン風コータム（砕米ご飯）の店。炭火焼きポークチョップ付き、南部庶民の味の代表格。',
   'このコータムの店では、炭火で焼いた豚のチョップ、揚げ豚皮(ビ)・蒸し卵を甘酢ヌクマムとともに提供する。この地域で働く人たちの毎日の昼食・夕食だ。コータムの店としてよく知られ、ベトナム伝統の味を地道に守っている。目玉メニューは炭火焼き豚チョップで、味を刺し込んだ豚肉が赤い炭火で焼かれると、色彩が美しく、特有のスモーク香りが出て、止められぬ味になる。付け合わせには、カリカリに揚げた豚皮「ビ」やフワフワ蒸し卵などがあって、それぞれの好みに合わせて選べるのが嬉しい。店が独力でブレンドした甘酢ヌクマムは、塩・甘・酸のバランスが絶妙で、豚チョップによく絡み全体の味をいくつもの段に引き上げる。コータムには豚ソーセージ、トマト、玉ねぎが追加され、複雑かつよい味になる。ここは単なる小飯屋ではなく、労働者や学生が授業や外出の後に立ち寄る待ち合わせ場所でもある。プラスチックの椅子、日差しがいっぱいのストリートダイニング空間、足元に残る炭の匂いがユニークな空気をつくる。青白い壁が色あせ、ガラス窓の向こうで正午の太陽が揺れる。炭火係は夜遅くまで炭火を守り続ける。常連は毎週のようにやって来る。まだ赤子だった頃から来ている人も、今は遠くで働く人も、みんなこの味を忘れられず足を運んでいる。',
   '豚チョップは炭火で香ばしく焼かれ、壊れた米は粒立ちよく、揚げ豚皮と蒸し卵が添えられる。ヌクマムだれにはトマトと炒め玉ねぎの風味が加わる。ヴィン・カイン通りは昔から4区で最も賑わうグルメ街で、手頃な価格のコータム店が集まっている。店は当初、扇風機1台、ヌクマムの大きな壺、味を染みこませた肉片から始まった。コータムは昔、貧しい人たちの食事だったが、今ではサイゴンに来る誰もが見逃せないストリートフードの頂点になった。店の外では青白壁が歳月で色あせ、正午の光が窓に揺らめく。炭火係は深夜まで火を起こし、肉を裏返し続ける。常連は毎週やってきて、まだ赤ん坊だった頃から通っている人も、今は遠くで働く人たちもその味を求め足を運ぶ。',
   'コータムは壊れた米を活かした南部の国民食とされ、今やサイゴンのストリートフードの象徴となっている。コータムは捨てられかけたものを再び光らせる創造性としのぎを削る知恵の味だ。料理人の誠実さ、炎の前で汗をかく手、味の技術は壁を越えて庶民の結びつきにつながり、それが1杯のコータムをそれぞれの物語をつつんだストリートフードの印として残している。',
   '11時〜13時は混みますので少しお待ちいただくことがあります • 目玉焼きやチャーサイジを追加すると美味しさアップ • ヌクマムを少しつけて小粒のこくを閉じ込めます • ストリートフードでも体は大事に、ほどほど楽しみましょう'),
  ('banh-xeo-hoa-gia', 'バイン・セオ・ホア・ザー',
   '炭火で焼き上げるサクサクのベトナムバンセオを、野菜と巻いて食べる南部味覚の正当派。',
   'バイン・セオは薄くサクサクのクレープに海老・豚肉・もやしを入れ、注文を受けたら焼くため、サクサク感が続く。レタスやハーブ、ライスペーパーで巻き、甘酢ヌクマムにつけて食べる料理だ。主原料は米粉・ウコン・エビ・豚肉・豆もやし・新鮮野菜で、伝統のレシピと手腕が合わさり、毎枚黄金色のサクサク皮ができる。 焼きたては、噛んだ時のカリカリ感、海老や豚肉の旨味、ウコンの香りが合わさって広がりを持つ。サイゴン式はレタス・ミント・漬物野菜と巻いて、にんじん・大根の漬物が入った甘酢ヌクマムにつけるのが一般だ。単なる一品を超え、バイン・セオは生き生きしたストリート雰囲気を醸し出し、ユーモア・家族的な情・分け合う心を生む結びつきになっていく。バイン・セオこそ南部日常の真髄を見せる食品であり、簡素で身近で、温かみのある一場面のようなものだ。',
   'サイゴンの人たちはバイン・セオをレタス・ミント・いろんな香草と一緒に巻き、にんじんと大根の漬物が入ったヌクマムにつけて食べるのが一般的だ。グエン・コアイ通り沿いのバイン・セオの屋台は長年、家族経営の路地 stalls として地元住民に親しまれてきた。バイン・セオは稲作の季節や澄んだ水、失わない味覚への季節とつながっており、季節の変わり目と土地で育った食材の近さが両方味わえる。昔から川沿いのこの道にあるバイン・セオ屋台は地元中小企業の形で長く続いてきたのだ。',
   'バイン・セオはウコンによる黄金色と新鮮なハーブが特徴で、南部食文化の融合を示す料理だ。バイン・セオは南部の料理の混ざり合い、ウコンの金色と家で取ったハーブ、伝統と変化を込めて、日常の中にどんな味があるかを教えてくれる。さらにこの料理は、苦しい頃の一握りの米から始まった知恵が、今は一個の皿に和らぐ記憶へと続いたことを伝えている。',
   '焼きたての熱いうちに食べるのが一番サクサクです • つけやすく小さめに巻いてみてください • 多くの店は現金のみですので、現金をご用意ください • 屋外の炭火の味を楽しみたい方は楽な格好で訪れてください'),
  ('bun-rieu-ben-van-don', 'ブン・リエウ・ベン・ヴァン・ドン',
   '蟹の甘い澄んだスープのブン・リエウ、生野菜と酸蝦とともに、川沿い朝の透き通った味。',
   '蟹みそが固まったスープは澄んで甘く、生麺・豆腐・トマト・各種生野菜と一緒に出る。川の近くのエリアでよくある朝食・昼食だ。淡水蟹をすりつぶして濾した蟹みそをトマトとともに煮込み、自然な赤みがでる。麺には酸蝦・空芯菜・もやし・バナナの花の千切りが付く。ベン・ヴァン・ドン一帯は河岸に近く、昔から地元住民の朝食を支える食堂が集まっていた。ブン・リエウは南部を代表する朝食で、水郷の食事らしいあっさりした味つけを表している。',
   '淡水蟹を擦り潰して濾した蟹みそを、トマトとともに煮ると自然な赤色が出る。麺には酸蝦・空芯菜・もやし・バナナの花の千切りがつき、川沿いの地区に住む人々の朝食は昔からこの地区で提供されてきた。川が近いからこそ、清々しい朝という気分を起こさせる。',
   'ブン・リエウは南部を代表する朝食で、水郷の食事らしいあっさりした味つけを示す。ブン・リエウは川がつくる朝の静けさ、道路の日常リズム、川の水に頼って暮らした人たちのご飯のあり方をそのまま反映している。霧のかかる朝には、もう薪は消えているのにかまどは残る光景がこの食べ物の歴史をつたえる。',
   'こってり好きなら蟹みそを追加してください • カラマンチュウを搾ると風味が引き立ちます • 多くの店がカードを断る場合があるため現金をお持ちください'),
  ('pho-an-vinh-khanh', 'ヴィン・カイン夜食ストリート',
   '4区で最も賑わう夜食街。海鮮焼き・貝料理・鍋が揃う、夜がくると立ち上がる食の舞台。',
   '日が暮れるとヴィン・カイン通りは夜食の街に変わる。通り沿いにプラスチックテーブルが並び、海鮮焼きと鍋の香りが漂う。サイゴンの夜のリズムを感じるのに最高の場所だ。通り沿いの屋台では海鮮焼き・どんな貝料理・魚の鍋・海鮮おかゆなどを出す。夜19時〜23時が最も混む時刻だ。この通りは港地区の住民の夜食ニーズから始まり、次第に全市の常連が集う夜中グルメストリートへと伸長した。ヴィン・カインの夜食文化はプラスチック椅子に座り生臭くも爽やかな料理を楽しみながら深夜までしゃべるサイゴンのオープンな暮らしそのものを映している。',
   'ヴィン・カイン通りは日が暮れると町全体が夜食ストリートに一変し、プラスチックテーブルが整然と並び、海鮮グリルや鍋の匂いが広がる。沿道の屋台では焼き海鮮・各種の貝・魚の鍋・海鮮おかゆも出ている。19時から23時がもっとも人通りが多く、匂いが路上全体に行きわたる。当初、この通りは港周辺の住民の夜遅い食事の必要から出発し、やがて市全体の人が日常的に寄る深夜グルメの拠点に拡大した。プラスチック椅子に腰掛け、フレッシュな料理を分け合い、夜遅くまで語らう様子はサイゴンのスローな夜文化をそのまま写し出すものだ。',
   'ヴィン・カイン通りは最初の出発点から港周辺住民の夜遅い食事の必要に応じて始まり、やがて市全体の人々が日常的に集まる深夜グルメの場所へと拡大した。ここはストリートフードの全盛期、夜市の雰囲気と光・音・匂いが混ざり合う立ち現われるストリート美学だ。ヴィン・カイン通りの人々はすでに40〜50年以上にわたりこの通りで夜食のエネルギッシュな情けを分け合ってきたのだ。',
   'グループで訪れて複数の料理をシェアするのがおすすめ • 現金のみの店が多いので現金をご用意ください • 1日の終わりでも食卓の笑いが絶えないヴィン・カインで、ゆっくり夜の味に自分を浸してみてください'),
  ('cho-quan-4', '4区市場',
   '朝食屋台・果物・南部の特産品が集まる伝統市場。地元食材の元祖取引の現場。',
   '4区市場には朝食の屋台、新鮮な果物、菓子や海産物の乾物店が集まっている。伝統的なサイゴン式市場の雰囲気の中で、地元の食文化を探検するのに最適だ。市場内の屋台ではブン・マム・フーティウ・バイン・カン・南部果物・乾魚などが売られている。朝が市場で最も混み合う時間。数十年、この市場は4区住民の食材購入の中心であり、近隣地区にもフレッシュな食材を供給し続けてきた。伝統市場は現代ショッピングモールと異なり、地元民の売り買い・料理・食事の原型を保っている。',
   '4区市場の屋台にはブンマム・フーティウ・バインカン・南部郷土の果物・干魚などが並び、最も慌ただしいのは朝の時間だ。数十年にわたりこの市場は4区の住民の食材購入の中心にあって、隣接する居住地に新鮮な原材料を供給してきた。伝統市場は現代ショッピングモールと対照的に、地元民の売買・調理・食事の原初的な姿をそのまま抱擁する場所だ。',
   '4区の伝統市場は町の食料補給のしっかりした中心であったと同時に、郷土の商人・料理・食事の原始的な風景を保有する生きた空間だ。市場は歳月が経っても本来のヒト臭さ・ビニールテント・集めた笑い・朝の光に反射する果物の光などをそのまま守り、都会人の心を安らかで自然に混ぜ合わせる。',
   '小銭を用意すると買いやすくなります • その場で食べられる朝食メニューを売り子さんにおすすめしてもらいましょう'),
  ('cafe-ben-van-don', 'ベン・ヴァン・ドン川沿いカフェ',
   '運河を見下ろす川沿いカフェ。朝夕の散歩にピッタリ、緩やかなサイゴン水辺の時。',
   '川に向かって開かれた空間で、ミルクコーヒー（カフェ・スア・ダー）・ココナッツコーヒー・フルーツティーを提供している。グルメ店が密集する4区でほっと一息つける場所である。カフェはベン・ヴァン・ドン通り沿い、運河を見下ろす位置にあり、店先の席から行き交う船を眺められる。ベン・ヴァン・ドンはかつてこの地域で盛んだった河港で、現在は4区と1区を結ぶ通りだ。サイゴンの路上コーヒー文化は、騒がしい都会の中でゆったりとした生活のリズムを表している。',
   'カフェはベン・ヴァン・ドン通りに沿って位置し、目の前に広がる運河と行き来する船がよく見える。ベン・ヴァン・ドンは昔、この地域で盛んな港であり、現在は第四区と第一区をつなぐ忙しい通りになっている。当時、荷物を積んだ船や行き交う人々の暮らしが川面にかすかに残っているかのようだ。',
   'サイゴンの路上コーヒー文化は、せわしない都会の中心でゆっくり生きるリズムを現わしている。この川沿いカフェは、点々と続く沿道の食堂群にあってもひと息つき、川辺の風景、通り過ぎる船を眺め、日常の速度を緩める場所である点に意味がある。',
   '早朝は涼しく、船が行き交う様子が見られます • 伝統的なフィン（ドリップ）式ミルクコーヒーを注文してみてください'),
  ('che-heo-quay', 'チェー（伝統スイーツ）店',
   '路地の伝統デザート店。ミックスチェーと白玉風チェーが名物、午後の路地の甘さを伝える。',
   'ミックスチェーの一椀に緑豆・タロイモ・タピオカ・ coconut cream が凝縮。ほかに白玉チェー・タイ風チェーもあり、夕方地元民に愛されるデザートのスポットだ。チェーは毎日炊きたてで、午後から夜まで提供される。各種のチェーにはココナッツクリームのまろやかな甘みがあり、南部風味がよく出ている。こうしたデザートの小さな屋台は路地の奥に店を構え、長年、地域住民に愛されてきた。チェーは南部のデザート文化で、緑豆・タロイモ・ココナッツなど水郷の豊かな素材を反映している。',
   'ミックスチェーには緑豆・タロイモ・タピオカ・ココナッツクリームが混ざり、白玉チェー・タイ風チェーも一緒に出される。チェーは毎日新たに作られ、午後から深夜まで販売されており、ココナッツクリームの深い甘みは南部独自の風味をよく表している。路地の奥まったところにあるこうしたデザートの小さい屋台は、何年も地元民に親しまれ継承されてきたのである。',
   'チェーは南部のデザート文化であり、緑豆・タロイモ・ココナッツなどのデルタ域で豊富な農産物を反映している。チェーは、一杯のなかに旬の素材と人びとの素朴な味覚が重ねられ、甘さが長く残る路地の情緒をつくりだすものである。',
   '夜に食べる場合は氷を少なめに頼みましょう • 炒りピーナッツをかけると香ばしさが加わります'),
  ('banh-canh-cua-nguyen-khoai', 'バイン・カン・クア（蟹）グエン・コアイ',
   '蟹の甘くとろみのあるスープ入り太麺。グエン・コアイエリアの朝名物、川辺の朝飯の濃厚スープ。',
   '米粉とタピオカ粉から作るもちもちの太麺に、蟹肉と豚骨で煮込んだとろみスープ、蟹すり身団子・エビ・シナモンスナックが付く。4区のこってり系の朝の食事だ。身入りの肉蟹は甘くてかみごたえがあり、蟹と豚骨を一緒に煮込むことでスープは自然にコクが出てくる。もやし・ねぎ・挽きたて胡椒・少々の唐辛子が絡み合う。グエン・コアイ通り沿いの蟹バイン・カンの屋台は長年、家族単位の朝食屋台として地域民に料理を提供してきた。蟹バイン・カンは多くの人に川辺エリアの朝料理文化の代表だとみなされている。',
   '身入りの肉蟹は甘さと咀嚼感が際立ち、蟹と豚骨を一緒に煮込むとスープは自然にコクを帯びる。麺にはもやし・ねぎ・挽きたてコショウ・少々唐辛子が付いており、グエン・コアイ通りの蟹バイン・カンの屋台は長年ファミリー単位の朝食の屋台として近所の住民に食事を供給してきた。川沿いのエリアではこのこってりした朝のスープで数多くの1日を起こしてきたのである。',
   '蟹バイン・カンは多くの人にとって川沿いエリアの朝のフードカルチャーのシンボルのような食べ物とみなされている。蟹バイン・カンは？蟹が出す固い甘みと真心込めて煮出したスープが、川近くの朝の重みと人たちの生活の質感を露わにしているのである。川辺の朝、もう立ちかかったスープのせきだけでも、朝を迎える気分がしてくるのである。',
   'お好みであればシナモン団子を追加してください • 塩漬けトマトを添えるとくどさが軽くなります'),
  ('hutieu-ca-men', 'ミトー・フーティウ',
   '透き通って甘いスープのミトー風フーティウ。新鮮なエビ・ニラ・揚げニンニクを添え、川南湾式の味。',
   'ミトー風フーティウの一椀：ほんのりピンクがかったもちもち麺に、新鮮なエビ・豚肉・肝・チンゲンサイ・透き通って甘いスープが調和する。フーティウの麺は米粉にエビを混ぜて薄いピンク色にしており、スープは豚骨と魚醤で軽やかに煮立てられる。この店はミトースタイルを守り、長年、ドアン・ニュー・ハイ地区の住民に親しまれてきた。フーティウは南部におけるベトナム・中華・クメール食文化の融合を示し、スープ入りと汁なしの両スタイルが一般的だ。',
   'フーティウ麺は米粉にエビを混ぜて淡いピンクがかり、スープは豚骨と魚醤でやわらかく煮出される。この店はミトースタイルにして何年ものあいだドアン・ニュー・ハイ地区の住民に食事を出してきた。フーティウはベトナム・中華・クメールの料理が混ざり合う姿を示し、スープ入りと汁なしの2スタイルともに一般的に味わえる。',
   'フーティウは南部でベトナム・中国・クメール料理が入り混じる様子をあらわにし、スープ入りと汁なしの2スタイルともに一般的に楽しめる。フーティウのスープの香り、ミトー独白の麺色、エビ・醤・空芯菜の配列は川人が長らく守ってきた味の一例として南部の多文化来歴と接触している。',
   'スープ入りと汁なしの両方を試してみてください • 唐辛子酢を少し加えるとスープの味に深みが出ます')
) AS v(code, name, short_desc, descr, history, culture, tips)
JOIN culinary_places p ON p.code = v.code
JOIN languages l ON l.code = 'ja'
ON CONFLICT (entity_type, entity_id, language_id) DO NOTHING;

